  return (
    <div
      style={{
        width: '100%',
        display: 'flex',
        justifyContent: 'center',
      }}>
      <Popover open={open} align={args.align}>
        <div className="playground-trigger">
          <CheckboxIcon
            onClick={() => {
              setOpen(!open);
            }}
          />
        </div>
        <PopoverContent className="p-3">
          <div>
            <p className="popover-title">This popover uses autoAlign</p>
            <p className="popover-details">
